body:
{
  "status": "success",
  "message": "Available Jenkins jobs",
  "jobs": {
    "docker-scan": {
      "name": "docker-scan",
      "description": "Triggers a Docker security scan for the specified image",
      "parameters": {
        "IMAGE_FULL_NAME": {
          "description": "Full Docker image name including tag (e.g., alpine:3.19)",
          "required": true,
          "type": "string",
          "default": null,
          "choices": null
        }
      }
    },
    "build": {
      "name": "build",
      "description": "Triggers a build job with configurable parameters",
      "parameters": {
        "BRANCH": {
          "description": "Git branch to build",
          "required": false,
          "type": "string",
          "default": "main",
          "choices": null
        },
        "BUILD_TYPE": {
          "description": "Type of build to perform",
          "required": false,
          "type": "string",
          "default": "release",
          "choices": [
            "debug",
            "release",
            "test"
          ]
        },
        "CLEAN_BUILD": {
          "description": "Whether to perform a clean build",
          "required": false,
          "type": "boolean",
          "default": "false",
          "choices": null
        }
      }
    },
    "Pipeline central-release-promotion": {
      "name": "Pipeline central-release-promotion",
      "description": "Promotes OpenSearch and OpenSearch Dashboards release candidates to final release. Requires release version and RC build numbers for both OpenSearch and OpenSearch Dashboards.",
      "parameters": {
        "RELEASE_VERSION": {
          "description": "Release version (e.g., 2.11.0, 3.0.0)",
          "required": true,
          "type": "string",
          "default": null,
          "choices": null,
          "validation_pattern": "^\\d+\\.\\d+\\.\\d+$"
        },
        "OPENSEARCH_RC_BUILD_NUMBER": {
          "description": "OpenSearch Release Candidate Build Number",
          "required": true,
          "type": "string",
          "default": null,
          "choices": null
        },
        "OPENSEARCH_DASHBOARDS_RC_BUILD_NUMBER": {
          "description": "OpenSearch Dashboards Release Candidate Build Number",
          "required": true,
          "type": "string",
          "default": null,
          "choices": null
        }
      }
    }
  },
  "total_jobs": 3
}
